head.b:skin:
:root {
  --background-color: #0f172a;
  --bg-gradient: radial-gradient(circle at top left, #1e293b, #0f172a);
  --text-color: #f1f5f9;
  --text-muted: #94a3b8;
  --primary-color: #38bdf8;
  --primary-glow: rgba(56, 189, 248, 0.4);
  --error-color: #f43f5e;
  --success-color: #10b981;
  --input-background: #1e293b;
  --input-border: #334155;
  --button-hover: #0ea5e9;
  --card-background: rgba(30, 41, 59, 0.7);
  --ad-background: rgba(255, 255, 255, 0.03);
  --ad-text: #475569;
  --nav-bg: rgba(15, 23, 42, 0.8);
}

body.light-mode {
  --background-color: #f8fafc;
  --bg-gradient: radial-gradient(circle at top left, #ffffff, #f1f5f9);
  --text-color: #1e293b;
  --text-muted: #64748b;
  --primary-color: #0284c7;
  --primary-glow: rgba(2, 132, 199, 0.2);
  --error-color: #e11d48;
  --success-color: #059669;
  --input-background: #ffffff;
  --input-border: #e2e8f0;
  --button-hover: #0369a1;
  --card-background: rgba(255, 255, 255, 0.9);
  --ad-background: rgba(0, 0, 0, 0.03);
  --ad-text: #94a3b8;
  --nav-bg: rgba(255, 255, 255, 0.8);
}

* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: 'Inter', sans-serif;
  background: var(--background-color);
  color: var(--text-color);
  line-height: 1.6;
  background-image: var(--bg-gradient);
  background-attachment: fixed;
  transition: all 0.4s ease;
}
header {
  position: sticky; top: 0; width: 100%; background: var(--nav-bg);
  backdrop-filter: blur(12px); z-index: 100; border-bottom: 1px solid var(--input-border);
}
nav {
  max-width: 1200px; margin: 0 auto; display: flex; justify-content: space-between;
  align-items: center; padding: 0.75rem 2rem;
}
.logo { font-weight: 800; font-size: 1.25rem; color: var(--primary-color); text-decoration: none; }
.nav-links { display: flex; gap: 1.5rem; list-style: none; align-items: center; }
.nav-links a { text-decoration: none; color: var(--text-color); font-size: 0.9rem; font-weight: 500; cursor: pointer; }
.nav-links a.active { color: var(--primary-color); }

.container { max-width: 1000px; margin: 2rem auto; padding: 0 1.5rem; display: flex; flex-direction: column; align-items: center; gap: 3rem; }
.page-section { display: none; width: 100%; flex-direction: column; align-items: center; gap: 2rem; }
.page-section.active { display: flex; }

main#checker { text-align: center; background: var(--card-background); padding: 3rem; border-radius: 24px; box-shadow: 0 20px 50px rgba(0,0,0,0.3); width: 100%; max-width: 700px; backdrop-filter: blur(20px); border: 1px solid var(--input-border); }
h1 { font-size: 2.5rem; font-weight: 900; margin-bottom: 1rem; background: linear-gradient(to right, var(--primary-color), #818cf8); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
.lead { color: var(--text-muted); margin-bottom: 2rem; font-size: 1.1rem; }

.form-group { width: 100%; margin-bottom: 1.5rem; }
input#password-input { width: 100%; padding: 1.2rem; border: 2px solid var(--input-border); border-radius: 16px; background: var(--input-background); color: var(--text-color); font-size: 1.1rem; transition: all 0.3s; }
input#password-input:focus { border-color: var(--primary-color); box-shadow: 0 0 0 4px var(--primary-glow); outline: none; }
button[type='submit'] { width: 100%; padding: 1.2rem; border: none; border-radius: 16px; background: var(--primary-color); color: #fff; font-size: 1.2rem; font-weight: 800; cursor: pointer; transition: all 0.3s; box-shadow: 0 10px 15px -3px var(--primary-glow); }
button[type='submit']:hover { transform: translateY(-2px); background: var(--button-hover); }

.trust-badge-container { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 1.5rem; width: 100%; margin-top: 2rem; }
.trust-badge { background: var(--input-background); padding: 1.5rem; border-radius: 16px; border: 1px solid var(--input-border); text-align: left; }
.trust-icon { font-size: 1.5rem; margin-bottom: 0.5rem; display: block; }

.info-section { background: var(--card-background); padding: 3rem; border-radius: 24px; border: 1px solid var(--input-border); text-align: left; }
.info-section h2 { margin-top: 2rem; margin-bottom: 1rem; color: var(--primary-color); }
.content-list { margin-left: 1.5rem; margin-bottom: 1.5rem; }
.content-list li { margin-bottom: 0.5rem; }

.ad-wrapper { width: 100%; max-width: 728px; min-height: 90px; background: var(--ad-background); border: 1px dashed var(--ad-text); display: flex; justify-content: center; align-items: center; border-radius: 12px; overflow: hidden; }

footer { width: 100%; padding: 4rem 2rem; background: var(--nav-bg); border-top: 1px solid var(--input-border); margin-top: 4rem; }
.footer-content { max-width: 1200px; margin: 0 auto; display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 3rem; }
.copyright { text-align: center; margin-top: 3rem; color: var(--ad-text); font-size: 0.8rem; }

.theme-toggle { background: var(--input-background); border: 1px solid var(--input-border); color: var(--text-color); padding: 0.5rem; border-radius: 50%; cursor: pointer; width: 40px; height: 40px; display: flex; align-items: center; justify-content: center; }

b:includable.script:
//
  function showSection(id) {
    document.querySelectorAll('.page-section').forEach(s => s.classList.remove('active'));
    document.getElementById(id).classList.add('active');
    document.querySelectorAll('.nav-links a').forEach(a => a.classList.remove('active'));
    const targetNav = document.getElementById('nav-' + id);
    if(targetNav) targetNav.classList.add('active');
    window.scrollTo({top: 0, behavior: 'smooth'});
  }
  const form = document.getElementById('password-checker-form');
  if (form) {
    form.addEventListener('submit', async (e) => {
      e.preventDefault();
      const pwd = document.getElementById('password-input').value;
      const res = document.getElementById('result-container');
      res.innerHTML = '<div style="color:var(--primary-color); text-align:center; padding:2rem; font-weight:700;">글로벌 보안 데이터베이스 대조 중...</div>';
      try {
        const hashBuffer = await crypto.subtle.digest('SHA-1', new TextEncoder().encode(pwd));
        const hashArray = Array.from(new Uint8Array(hashBuffer));
        const hashHex = hashArray.map(b => b.toString(16).padStart(2, '0')).join('').toUpperCase();
        const prefix = hashHex.slice(0, 5);
        const suffix = hashHex.slice(5);
        const response = await fetch('https://api.pwnedpasswords.com/range/' + prefix);
        const data = await response.text();
        const match = data.split('\n').find(line => line.startsWith(suffix));
        if (match) {
          const count = match.split(':')[1];
          res.innerHTML = `
            <div style="color:#f43f5e; margin-top:2rem; padding:2.5rem; background:rgba(244,63,94,0.1); border-radius:24px; border:2px solid #f43f5e; text-align:center;">
              <h3 style="color:#f43f5e; margin-bottom:1.5rem; font-size:1.8rem;">⚠️ 유출 위험 감지</h3>
              <p style="color:#f43f5e; font-size:1.2rem;">해당 비밀번호는 약 <strong>${parseInt(count).toLocaleString()}번</strong>의 데이터 유출 사고에서 발견되었습니다.</p>
              <button onclick="showSection('guide')" style="margin-top:2rem; padding:0.8rem 2rem; border-radius:12px; border:none; background:#f43f5e; color:white; cursor:pointer; font-weight:800;">대처 방법 보기</button>
            </div>`;
        } else {
          res.innerHTML = `<div style="color:#10b981; margin-top:2rem; padding:2.5rem; background:rgba(16,185,129,0.1); border-radius:24px; border:2px solid #10b981; text-align:center;"><h3 style="color:#10b981; margin-bottom:1.5rem; font-size:1.8rem;">✅ 안전함</h3><p style="color:#10b981; font-size:1.2rem;">현재까지 알려진 데이터 유출 사고에서 발견되지 않았습니다.</p></div>`;
        }
      } catch (err) { res.innerHTML = '<div style="color:#f43f5e; text-align:center; padding:2rem;">보안 서버 통신 오류가 발생했습니다.</div>'; }
    });
  }
  const toggle = document.getElementById('theme-toggle');
  if (toggle) {
    toggle.addEventListener('click', () => {
      document.body.classList.toggle('light-mode');
      localStorage.setItem('theme', document.body.classList.contains('light-mode') ? 'light' : 'dark');
    });
  }
  if(localStorage.getItem('theme') === 'light') document.body.classList.add('light-mode');
  (function() {
    var d = document, s = d.createElement('script');
    s.src = 'https://https-yanghyunmo44-hub-github-io-coding-practive.disqus.com/embed.js';
    s.setAttribute('data-timestamp', +new Date());
    (d.head || d.body).appendChild(s);
  })();
//
